class GachaGame extends GameEngine{constructor(t,n,e){super(t,"gacha",n),this.prizes=e,this.pityCount=n.pity_count||0,this.pityThreshold=n.pity_threshold||50,this.pulls=[],this.totalPulls=0}render(t){const n=`\n      <div class="game-container">\n        <div class="game-header">\n          <h2>✨ Gacha - Triệu Hồi</h2>\n          <p>Lấy giải thưởng bí mật mỗi lần triệu hồi</p>\n          <div class="timer" id="timer">0s</div>\n        </div>\n\n        <div class="gacha-container">\n          <div class="pull-buttons">\n            <button class="pull-button" id="pullBtn1" onclick="gachaPull(1)">\n              🎟️ 1 Lần Quay\n            </button>\n            <button class="pull-button bulk" id="pullBtn10" onclick="gachaPull(10)">\n              🎟️⨯10 Quay (10% Giảm)\n            </button>\n          </div>\n\n          <div class="pulls-result" id="pullResult"></div>\n\n          <div class="pity-status">\n            <div class="pity-label">Pity Counter (Đảm bảo SSR/Legendary)</div>\n            <div class="pity-progress">\n              <div class="pity-bar" id="pityBar" style="width: ${this.pityCount/this.pityThreshold*100}%"></div>\n            </div>\n            <div class="pity-count">\n              <span id="pityCount">${this.pityCount}</span> / ${this.pityThreshold}\n            </div>\n          </div>\n\n          <div class="gacha-stats">\n            <p>Tổng Quay: <strong id="totalPullsCount">0</strong></p>\n          </div>\n        </div>\n      </div>\n    `;document.getElementById(t).innerHTML=n,this.startTimer()}getRandomPrize(){const t=Math.random();let n;n=t<.7?t=>"common"===t.rarity||"uncommon"===t.rarity:t<.95?t=>"rare"===t.rarity||"epic"===t.rarity:t=>"legendary"===t.rarity||"mythic"===t.rarity;const e=this.prizes.filter(n);return e.length>0?e[Math.floor(Math.random()*e.length)]:this.prizes[Math.floor(Math.random()*this.prizes.length)]}playSound(t){const n=new(window.AudioContext||window.webkitAudioContext),e=n.createOscillator(),i=n.createGain();e.connect(i),i.connect(n.destination),e.frequency.value={common:440,uncommon:550,rare:660,epic:770,legendary:1e3,mythic:1200}[t]||440,e.type="sine",i.gain.setValueAtTime(.3,n.currentTime),i.gain.exponentialRampToValueAtTime(.01,n.currentTime+.5),e.start(n.currentTime),e.stop(n.currentTime+.5)}async pull(t){const n=document.getElementById("pullBtn1"),e=document.getElementById("pullBtn10");n.disabled=!0,e.disabled=!0;const i=[];for(let n=0;n<t;n++){const t=this.getRandomPrize();i.push(t),this.pulls.push(t),this.totalPulls++,this.pityCount++,"legendary"!==t.rarity&&"mythic"!==t.rarity||(this.pityCount=0),this.pityCount>=this.pityThreshold&&(i[i.length-1]=this.prizes.find(t=>"legendary"===t.rarity)||t,this.pityCount=0),this.playSound(t.rarity),await new Promise(t=>setTimeout(t,300))}const s=this.pityCount/this.pityThreshold*100;document.getElementById("pityBar").style.width=s+"%",document.getElementById("pityCount").textContent=this.pityCount,document.getElementById("totalPullsCount").textContent=this.totalPulls;const a=i.map((t,n)=>`\n      <div class="pull-item ${t.rarity}" style="animation-delay: ${100*n}ms">\n        <div class="pull-item-emoji">${t.icon||"💎"}</div>\n        <div class="pull-item-name">${t.name}</div>\n        <div class="pull-item-rarity">${t.rarity}</div>\n        ${t.cash_amount?`<div class="pull-item-value">💰 ${t.cash_amount.toLocaleString()}đ</div>`:""}\n      </div>\n    `).join("");document.getElementById("pullResult").innerHTML=a,await new Promise(t=>setTimeout(t,1500)),this.endGame(this.prizes.indexOf(i[0])),n.disabled=!1,e.disabled=!1}endGame(t){this.state="completed";const n=this.prizes[t||0];this.selectedPrize=n;const e=this.getCompletionTime();console.log(`✅ Gacha game completed in ${e}s (${this.totalPulls} pulls)`),fetch("/api/game/result",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({session_code:this.sessionCode,game_type:this.gameType,prize_id:n.id,completion_time:e,extra_data:{total_pulls:this.totalPulls,pity_resets:0}})}).catch(t=>console.error(t)),this.showResultScreen(n)}showResultScreen(t){const n=t.color||"#8b5cf6",e=`\n      <div class="result-screen">\n        <div class="result-emoji" style="color: ${n}">✨</div>\n        <h2 class="result-title">Triệu Hồi Thành Công!</h2>\n        <p class="result-message">Bạn đã nhận được</p>\n        \n        <div class="result-detail">\n          <div style="font-size: 2.5rem; margin-bottom: 10px;">${t.icon||"✨"}</div>\n          <strong style="color: ${n}; font-size: 1.4rem;">${t.name}</strong>\n          <p style="color: ${n}; text-transform: uppercase; font-weight: bold; margin: 5px 0;">${t.rarity}</p>\n          ${t.cash_amount?`<p>💰 ${t.cash_amount.toLocaleString()}đ</p>`:""}\n          <p style="font-size: 0.9rem; opacity: 0.8;">Tổng Quay: <strong>${this.totalPulls}</strong></p>\n        </div>\n\n        <div class="result-buttons">\n          <button class="btn btn-primary" onclick="location.href='/thank-you'">\n            ✅ Nhận Thưởng\n          </button>\n          <button class="btn btn-secondary" onclick="shareResult()">\n            📤 Chia Sẻ\n          </button>\n        </div>\n      </div>\n    `;document.querySelector(".game-container").innerHTML=e}startTimer(){this.startTime=Date.now();const t=setInterval(()=>{const n=Math.floor((Date.now()-this.startTime)/1e3),e=document.getElementById("timer");e?e.textContent=n+"s":clearInterval(t)},1e3)}}function gachaPull(t){window.gachaGameInstance&&window.gachaGameInstance.pull(t)}console.log("✅ GachaGame class loaded");